head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용

scwin.vScrenID = "ULDSTF05244.xml";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.Isur_cd = "", scwin.Isur_nm = "", scwin.Secugrp_id = "", scwin.Mkt_id = "", scwin.fr_bz_procs_no = "";
scwin.vScrenProcTpCd = "";
scwin.TR_JOB;
scwin.vSECT_CHG_TP_CD;
scwin.vAFCHG_SECT_TP_CD;
scwin.vBFCHG_SECT_TP_CD;
scwin.vCHG_DD;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_searchCode = function() {
    /*
    00726 - 소속부유형코드
    01361 - 소속부변경구분코드
    01362 - 벤처유형코드
    */
    var arrCid = [{
        cid: "SECT_TP_CD",
        cnm: "cmb_BFCHG_SECT_TP_CD"
    }, {
        cid: "SECT_TP_CD",
        cnm: "cmb_AFCHG_SECT_TP_CD"
    }, {
        cid: "SECT_CHG_TP_CD",
        cnm: "cmb_SECT_CHG_TP_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='SECT_TP_CD','SECT_TP_CD','SECT_CHG_TP_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        //alert('[objCod]'+objCod);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                if (arrCid[i].cid == "SECT_TP_CD") {
                    if (j == 1) {
                        strCbd = strCbd + (strCbd == "" ? "" : ",") + '' + "^" + '=====================================';
                    }
                    if (dts_Cod.getCellData(j, "VALUE") == "X" || dts_Cod.getCellData(j, "VALUE") == "Y" || dts_Cod.getCellData(j, "VALUE") == "W") {
                        strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
                    }
                } else {
                    strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
                }
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.fn_read_sync = function() {
    var url = "/SectionTypeChange.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=readMarketAction&inputMessageId=SECT_TYP_CHG_INOUT";
    url += "&BZ_PROCS_NO=" + scwin.fr_bz_procs_no;
    dts_Item.DataID = encodeURI(url);
    dts_Item.Reset();
};
scwin.fn_BfSectTpCd = function() {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=SECT_TYP_CHG_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.konex.scttypchg.bfchgsecttpcd.select" + "&{P}param01=" + scwin.Isur_cd;
    dts_Item.DataID = encodeURI(url);
    dts_Item.Reset();
};
scwin.fn_CheckForm = function() {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
        $c.win.alert("[회사코드] 항목값이  없습니다.");
        txb_ISUR_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_SECT_CHG_TP_CD) == "") {
        $c.win.alert("[소속부변경구분]을 선택하세요.");
        cmb_SECT_CHG_TP_CD.focus();
        return false;
    }
    if (scwin.vSECT_CHG_TP_CD == 'N') {
        if (scwin.vSECT_CHG_TP_CD != $c.stf.getObjectValue(cmb_SECT_CHG_TP_CD)) {
            $c.win.alert("[소속부변경구분]값이 '신규상장'이면 [소속부변경구분]항목을 변경할 수 없습니다.");
            cmb_SECT_CHG_TP_CD.focus();
            return false;
            //심사팀에서 신규상장시 입력한 자료라서 수정 불가.
        }
        if (scwin.vBFCHG_SECT_TP_CD != $c.stf.getObjectValue(cmb_BFCHG_SECT_TP_CD)) {
            $c.win.alert("[소속부변경구분]값이 '신규상장'이면 [변경전소속부]항목을 변경할 수 없습니다.");
            cmb_BFCHG_SECT_TP_CD.focus();
            return false;
        }
        if (scwin.vAFCHG_SECT_TP_CD != $c.stf.getObjectValue(cmb_AFCHG_SECT_TP_CD)) {
            $c.win.alert("[소속부변경구분]값이 '신규상장'이면 [변경후소속부]항목을 변경할 수 없습니다.");
            cmb_AFCHG_SECT_TP_CD.focus();
            return false;
        }
        if (scwin.vCHG_DD != $c.stf.getObjectValue(edt_CHG_DD)) {
            $c.win.alert("[소속부변경구분]값이 '신규상장'이면 [변경일]항목을 변경할 수 없습니다.");
            edt_CHG_DD.focus();
            return false;
        }
    }
    if ($c.stf.getObjectValue(cmb_BFCHG_SECT_TP_CD) == 'X' && ($c.stf.getObjectValue(cmb_AFCHG_SECT_TP_CD) == 'Y' || $c.stf.getObjectValue(cmb_AFCHG_SECT_TP_CD) == 'W')) {
        $c.win.alert("[일반기업부]에서 [스타트업기업부] 또는 [크라우드펀딩기업부]로 소속부유형을 변경할 수 없습니다.");
        cmb_AFCHG_SECT_TP_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_BFCHG_SECT_TP_CD) == 'Y') {
        if ($c.stf.getObjectValue(cmb_AFCHG_SECT_TP_CD) == 'W') {
            $c.win.alert("[스타트업기업부]에서 [크라우드펀딩기업부]로 소속부유형을 변경할 수 없습니다.");
            return false;
        }
    } else if ($c.stf.getObjectValue(cmb_BFCHG_SECT_TP_CD) == 'W') {
        if ($c.stf.getObjectValue(cmb_AFCHG_SECT_TP_CD) == 'Y') {
            $c.win.alert("[크라우드펀딩기업부]에서 [스타트업기업부]로 소속부유형을 변경할 수 없습니다.");
            return false;
        }
    }
    if ($c.stf.getObjectValue(cmb_SECT_CHG_TP_CD) == "") {
        $c.win.alert("[소속부변경구분]을 선택하세요.");
        cmb_SECT_CHG_TP_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_SECT_CHG_TP_CD) != "N") {
        //신규상장이 아닐 경우
        if ($c.stf.getObjectValue(cmb_BFCHG_SECT_TP_CD) == "") {
            $c.win.alert("[변경전 소속부] 항목값이  없습니다.");
            cmb_BFCHG_SECT_TP_CD.focus();
            return false;
        }
    }
    if ($c.stf.getObjectValue(cmb_AFCHG_SECT_TP_CD) == "") {
        $c.win.alert("[변경후 소속부]를 선택하세요.");
        cmb_AFCHG_SECT_TP_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_BFCHG_SECT_TP_CD) == $c.stf.getObjectValue(cmb_AFCHG_SECT_TP_CD)) {
        $c.win.alert("[변경전 소속부]와 [변경후 소속부]가 동일합니다.");
        cmb_AFCHG_SECT_TP_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_CHG_DD) == "") {
        $c.win.alert("[변경일]을 입력하세요.");
        edt_CHG_DD.focus();
        return false;
    }
    if (vCurDate >= $c.stf.getObjectValue(edt_CHG_DD)) {
        $c.win.alert("[변경일]을 현재일이후로 입력하세요.");
        edt_CHG_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_SECT_STRT_DD) == "") {
        if ($c.stf.getObjectValue(edt_SECT_END_DD) != "") {
            $c.win.alert("[소속부유효시작일]을 입력하세요.");
            edt_SECT_STRT_DD.focus();
            return false;
        }
    } else {
        if ($c.stf.getObjectValue(edt_SECT_END_DD) == "") {
            $c.win.alert("[소속부유효종료일]을 입력하세요.");
            edt_SECT_END_DD.focus();
            return false;
        }
        if (parseInt($c.stf.getObjectValue(edt_SECT_STRT_DD), 10) > parseInt($c.stf.getObjectValue(edt_SECT_END_DD), 10)) {
            $c.win.alert("[소속부유효종료일]은 [소속부유효시작일]보다 작아야 합니다. 다시 입력해주세요");
            return false;
        }
    }
    return true;
};
scwin.fn_duplicate_check = function() {
    var url = "/SectionTypeChange.do?method=checkDuplicate&inputMessageId=SECT_TYP_CHG_DUP_CHK_OUT";
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
    url += "&CHG_DD=" + $c.stf.getObjectValue(edt_CHG_DD);
    dts_DUP_CHK.DataID = encodeURI(url);
    dts_DUP_CHK.Reset();
    return dts_DUP_CHK.getCellData(1, "DUP_CHK");
};
scwin.fn_drft = function() {
    var OldGet = scwin.fn_GetPar;
    scwin.fn_GetPar = function(arr) {
        arr[0] = scwin.fr_bz_procs_no;
        return arr.length;
    };
    $c.lc.fn_PopFindDraft();
    scwin.fn_GetPar = OldGet;
};
scwin.fn_dscl = async function() {
    var OldGet = scwin.fn_GetPar;
    var OldSet = scwin.fn_SetPar;
    scwin.fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        arr[0] = "32159";
        arr[1] = scwin.fr_bz_procs_no;
        arr[2] = scwin.Isur_cd;
        arr[3] = '6';
        $c.stf.CopyDataSet(dts_Item, param_dts_mst);
        return arr.length;
    };
    scwin.fn_SetPar = function(arr) {

    };
    var wth = 730 + 5;
    var hgt = 785 + 30;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "공시안내문작성", pt.x, pt.y, wth, hgt, "window");
    scwin.fn_GetPar = OldGet;
    scwin.fn_SetPar = OldSet;
};
scwin.fn_save = function() {
    scwin.TR_JOB = 'I';
    if (scwin.fn_CheckForm()) {
        if (scwin.fn_duplicate_check() == 'Y') {
            $c.win.alert("[변경일]이 동일한 일자로 이미  입력되었습니다.");
            return;
        }
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        scwin.fr_bz_procs_no = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
        if (scwin.fr_bz_procs_no.length != 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************

            /*ORG SRC: dts_Item.UserStatus(1) = TB_JOB_INSERT;*/
            X = TB_JOB_INSERT;
            dts_Item.setCellData(1, "BZ_PROCS_NO", scwin.fr_bz_procs_no);
            dts_Item.setCellData(1, "LIST_BZ_TP_CD", LIST_BZ_TP_CD_234);
            dts_Item.setCellData(1, "SPOT_ISU_TRD_MKT_TP_CD", /*ORG SRC: dts_Item.setNameString(1, "SPOT_ISU_TRD_MKT_TP_CD", dts_Item.NameString(1, "SPOT_ISU_TRD_MKT_TP_CD") = );*/ X = X);
            scwin.fn_trs();
        }
    }
};
scwin.fn_update = function() {
    scwin.TR_JOB = 'U';
    if (scwin.fn_CheckForm()) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return; /*ORG SRC: dts_Item.UserStatus(1) = TB_JOB_UPDATE;*/ X = TB_JOB_UPDATE;
        scwin.fn_trs();
    }
};
scwin.fn_delete = function() {
    scwin.TR_JOB = 'D';
    if (scwin.vSECT_CHG_TP_CD == 'N') {
        $c.win.alert("[소속부변경구분]값이 '신규상장'이면 삭제 할 수 없습니다.");
        cmb_SECT_CHG_TP_CD.focus();
        return;
        //심사팀에서 신규상장시 입력한 자료라서 삭제 불가(신규상장한건도 삭제처리됨.).
    }
    if (!$c.lc.fn_check_delete_discls(dts_BZ_CHECK, scwin.fr_bz_procs_no)) return;
    if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
    $c.cp.removeRow(dts_Item, dts_Item.getRowPosition());
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.
    scwin.fn_trs();
};
scwin.fn_trs = function() {
    if (scwin.TR_JOB == "I") {
        scwin.vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB == "U") {
        scwin.vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    } else if (scwin.TR_JOB == "D") {
        scwin.vScrenProcTpCd = SCREN_PROCS_TP_CD_04;
    }
    trs_Save.Action = $c.lc.fn_encodeNSession("/SectionTypeChange.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + scwin.vScrenProcTpCd + "&method=saveKonexSectionTypeChange");
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Item)";
    trs_Save.Post();
};
scwin.fn_parentRefresh = function() {
    var fr_fn_list_sync = $c.frame.path("../").fn_list_sync;
    fr_fn_list_sync();
};
scwin.dts_Item_OnLoadError = function() {
    $c.stf.alert_error(dts_Item);
};
scwin.dts_Item_OnLoadCompleted = function(rowcount) {
    txb_ISUR_CD.setValue(scwin.Isur_cd);
    txb_COM_NM.setValue(scwin.Isur_nm);
    scwin.vSECT_CHG_TP_CD = dts_Item.getCellData(1, "SECT_CHG_TP_CD");
    scwin.vAFCHG_SECT_TP_CD = dts_Item.getCellData(1, "AFCHG_SECT_TP_CD");
    scwin.vBFCHG_SECT_TP_CD = dts_Item.getCellData(1, "BFCHG_SECT_TP_CD");
    scwin.vCHG_DD = dts_Item.getCellData(1, "CHG_DD");
    // 조회가 완료되었을때 신규처리에 의한 조회인지,  수정에 의한 조회인지를 구별
    if (dts_Item.getCellData(dts_Item.getRowPosition(), "BZ_PROCS_NO") == "") {
        buttonSet.setInsertStatus();
    } else {
        var vCurDate = $c.ut.cGetToday("yyyymmdd");
        if (vCurDate <= $c.stf.getObjectValue(edt_CHG_DD)) {
            buttonSet.setUpdateStatus();
        } else {
            buttonSet.setErrorStatus(); //disable 시킨다.
            //alert('[DISCLS_YN]'+dts_IndustryChange.NameValue(1, "DISCLS_YN"));
            //setButtonSetWithDate2(dts_Item.NameValue(1, "DISCLS_YN"));

        }
    }
};
scwin.trs_Save_OnFail = function() {
    $c.lc.fn_alertMsg('F');
};
scwin.trs_Save_OnSuccess = async function() {
    $c.lc.fn_alertMsg('S');
    scwin.fn_parentRefresh();
    if (buttonSet.status == "D") {
        // 삭제처리의 응답인 경우
        await $c.frame.CloseFrame();
    } else {
        scwin.fn_read_sync();
    }
};
scwin.img_SECT_STRT_DD_onclick = function() {
    popUpCalendar2(edt_SECT_STRT_DD);
};
scwin.img_SECT_END_DD_onclick = function() {
    popUpCalendar2(edt_SECT_END_DD);
};
scwin.img_CHG_DD_onclick = function() {
    popUpCalendar2(edt_CHG_DD);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    var fnc = $c.frame.path("../").scwin.fn_GetPar; // Provider화면에서 fn_GetPar명칭으로 선언된 함수를 획득
    var arrPar = new Array();
    $c.elw.fn_searchCode();
    if (fnc != undefined) {
        fnc(arrPar); // Provider화면의 callback함수를 호출하여 필요한 인수를 넘겨받는다.
        scwin.Isur_cd = (arrPar.length >= 1 ? arrPar[0] : ""); // 발행기관코드
        scwin.Isur_nm = (arrPar.length >= 2 ? arrPar[1] : ""); // 발행기관명
        scwin.Secugrp_id = (arrPar.length >= 3 ? arrPar[2] : ""); // 증권그룹ID
        scwin.Mkt_id = (arrPar.length >= 4 ? arrPar[3] : ""); // 시장구분코드
        scwin.fr_bz_procs_no = (arrPar.length >= 5 ? arrPar[4] : ""); // 업무처리번호(수정시만 유효)

    }
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    buttonSet.setDeleteInfo(btn_Delete, fn_delete); // 삭제
    buttonSet.setDsclInfo(btn_Dscl, fn_dscl); // 안내문작성
    buttonSet.setDrftInfo(btn_Drft, fn_drft); // 기안
    if (scwin.fr_bz_procs_no != "") {
        // Provider화면 에서 넘겨받은 업무처리번호가 ""가 아니라면 신규작성으로 간주한다.
        scwin.fn_read_sync();
    } else {
        scwin.fn_BfSectTpCd();
    }
    $c.cm.PanelToGroupBox(panel_Top);

    //buttonSet.setButtonDepCd(dts_ByCorpDepCd, txb_ISUR_CD.value, js_dep_cd);

};
scwin.btn_Dscl_onclick = function() {
    scwin.fn_dscl();
};
scwin.dts_BZ_CHECK_OnLoadError = function() {
    4;
    $c.stf.alert_error(dts_BZ_CHECK);
};
scwin.cmb_AFCHG_SECT_TP_CD_OnSelChange = function() {
    if ($c.stf.getObjectValue(cmb_AFCHG_SECT_TP_CD) == "X") {
        $c.stf.setObjectValue(edt_SECT_END_DD, "99991231");
    }
};
